class Solution {
public:
    long long interactionCosts(int n, vector<vector<int>>& edges, vector<int>& group) {
        vector<vector<int>> adj(n);
        for (auto &e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        vector<int> parent(n, -1), order(1, 0);
        for (int i = 0; i < (int)order.size(); ++i) {
            int u = order[i];
            for (int v : adj[u]) if (v != parent[u]) {
                parent[v] = u;
                order.push_back(v);
            }
        }
        vector<array<int, 21>> cnt(n);
        array<int, 21> total = {};
        for (int i = 0; i < n; ++i) ++total[group[i]];
        long long ans = 0;
        for (int i = n - 1; i >= 0; --i) {
            int u = order[i];
            ++cnt[u][group[u]];
            if (parent[u] != -1) {
                for (int g = 1; g <= 20; ++g) {
                    ans += 1LL * cnt[u][g] * (total[g] - cnt[u][g]);
                    cnt[parent[u]][g] += cnt[u][g];
                }
            }
        }
        return ans;
    }
};
